module logic;
use model {Change,Edit};
use util {reverse};
fn run(text:Text,start:I64,count:I64,replacement:Text)->Edit<Change> {
 let length=Text::length(text);
 if start<0 || start>length {
  Err(1)
 } else {
  if count<0 || count>length-start {
   Err(2)
  } else {
   let prefix=Text::slice(text,0,start);
   let removed=Text::slice(text,start,count);
   let suffix=Text::slice(text,start+count,length-start-count);
   let combined=Text::concat(Text::concat(prefix,replacement),suffix);
   Ok(Change {
    text:combined,
    removed:removed,
    scalar_delta:Text::length(replacement)-count,
    byte_delta:Bytes::length(Text::bytes(combined))-Bytes::length(Text::bytes(text))
   })
  }
 }
}

